public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int maxSize = (int) Math.pow(3, n);
    char[][] result = new char[maxSize][maxSize];

    generateCarpet(result, 0, 0, maxSize, false);

    for (int j = 0; j < result.length; j++) {
        for (int i = 0; i < result.length; i++) {
            System.out.print(result[j][i]);
        }
        System.out.println();
    }

    scan.close();
}

private static void generateCarpet(char[][] result, int x, int y, int size, boolean isBlank) {
    if (isBlank) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                result[x + i][y + j] = ' ';
            }
        }
        return;
    }

    if (size == 1) {
        result[x][y] = '#';
        return;
    }

    int newSize = size / 3;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            generateCarpet(result, x + i * newSize, y + j * newSize, newSize, (i == 1 && j == 1));
        }
    }
}
